// examples/epistemic_mcts.sio
//
// Minimal epistemic PUCT demo: Beta posterior updates + ignorance bonus via stdlib policy.
//
// Run: artifacts/self-hosted/souc-self-hosted-x86_64 examples/epistemic_mcts.sio /tmp/out.elf && /tmp/out.elf
//
// Policy twin: stdlib/search/mcts/policy.sio::puct_epistemic (gated by tests/stdlib/search/test_mcts_policy.sio).

struct BetaResult {
    mean: f64,
    variance: f64
}

struct MCTSNode {
    prior_mean: f64,
    value_mean: f64,
    value_variance: f64,
    visits: f64,
    parent_visits: f64
}

fn max_f(a: f64, b: f64) -> f64 {
    if a > b { a } else { b }
}

fn beta_update(old_mean: f64, old_variance: f64, outcome: f64, weight: f64) -> BetaResult with Div {
    let safe_var = max_f(old_variance, 0.0001)
    let n_eff = old_mean * (1.0 - old_mean) / safe_var - 1.0
    let n_eff_safe = max_f(n_eff, 1.0)
    let new_mean = (old_mean * n_eff_safe + outcome * weight) / (n_eff_safe + weight)
    let new_n = n_eff_safe + weight
    let new_variance = new_mean * (1.0 - new_mean) / (new_n + 1.0)
    BetaResult { mean: new_mean, variance: new_variance }
}

fn sqrt_local(x: f64) -> f64 with Mut, Div {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess = (guess + x / guess) / 2.0
    guess
}

fn node_puct_score(node: MCTSNode, c_exploration: f64, c_ignorance: f64) -> f64 with Mut, Div {
    let parent_sqrt = sqrt_local(node.parent_visits)
    let u = node.prior_mean * parent_sqrt / (1.0 + node.visits)
    let safe_variance = max_f(node.value_variance, 0.0001)
    node.value_mean + c_exploration * u + c_ignorance * sqrt_local(safe_variance)
}

fn backprop_node(node: MCTSNode, outcome: f64) -> MCTSNode with Div {
    let result = beta_update(node.value_mean, node.value_variance, outcome, 1.0)
    MCTSNode {
        prior_mean: node.prior_mean,
        value_mean: result.mean,
        value_variance: result.variance,
        visits: node.visits + 1.0,
        parent_visits: node.parent_visits
    }
}

fn test_puct_scores() -> f64 with Mut, Div {
    let confident = MCTSNode {
        prior_mean: 0.3,
        value_mean: 0.7,
        value_variance: 0.01,
        visits: 10.0,
        parent_visits: 100.0
    }
    let uncertain = MCTSNode {
        prior_mean: 0.3,
        value_mean: 0.5,
        value_variance: 0.25,
        visits: 10.0,
        parent_visits: 100.0
    }
    node_puct_score(uncertain, 1.4, 0.8) - node_puct_score(confident, 1.4, 0.8)
}

fn test_beta_update() -> f64 with Div {
    let initial_mean = 0.5
    let initial_variance = 0.25
    let r1 = beta_update(initial_mean, initial_variance, 1.0, 1.0)
    let r2 = beta_update(r1.mean, r1.variance, 1.0, 1.0)
    let r3 = beta_update(r2.mean, r2.variance, 1.0, 1.0)
    (r3.mean - initial_mean) + (initial_variance - r3.variance)
}

fn main() with IO, Mut, Div {
    println("=== Epistemic MCTS (minimal) ===")
    let puct_test = test_puct_scores()
    println("PUCT epistemic advantage: ")
    println(puct_test)
    let beta_test = test_beta_update()
    println("Beta update metric: ")
    println(beta_test)
    let ok = puct_test > 0.01 && beta_test > 0.0
    if ok {
        println("EPISTEMIC_MCTS_PASS")
    } else {
        println("EPISTEMIC_MCTS_FAIL")
    }
}

//@ run-pass
// Phase 1 sanity test: second-order GUM variance collapses to first-order
// when the Hessian is identically zero (linear function).
//
// For f(x, y) = 3x + 4y, the Hessian is zero everywhere, so
//   σ²_2nd(f) = J^T Σ J + ½ tr(HΣHΣ) = J^T Σ J + 0 = σ²_1st(f)
//
// With sigma[0,0] = 0.01, sigma[1,1] = 0.04, sigma[0,1] = 0, J = [3, 4]:
//   σ²_1st = 9·0.01 + 16·0.04 = 0.73

// =============================================================================
// Inlined CovarianceMatrix (matches stdlib/epistemic/covariance.sio)
// =============================================================================

struct CovMat {
    n: i32,
    data: [f64; 300],
}

fn tri_idx_cov(n: i32, i: i32, j: i32) -> i32 with Mut {
    var row = i
    var col = j
    if i > j { row = j; col = i }
    return row * n - (row * (row - 1)) / 2 + (col - row)
}

fn cm_new(n: i32) -> CovMat {
    return CovMat { n: n, data: [0.0; 300] }
}

fn cm_set(cov: &!CovMat, i: i32, j: i32, val: f64) with Mut {
    let idx = tri_idx_cov(cov.n, i, j)
    cov.data[idx] = val
}

fn cm_get(cov: &CovMat, i: i32, j: i32) -> f64 with Mut {
    let idx = tri_idx_cov(cov.n, i, j)
    return cov.data[idx]
}

// =============================================================================
// Inlined second-order GUM variance (mirrors stdlib/epistemic/gum.sio)
// =============================================================================

fn hess_tri_idx_8(i: i32, j: i32) -> i32 with Mut {
    var r = i
    var c = j
    if r > c { r = j; c = i }
    return 8 * r - (r * (r - 1)) / 2 + (c - r)
}

fn hess_get_8(h: [f64; 36], i: i32, j: i32) -> f64 with Mut {
    return h[hess_tri_idx_8(i, j)]
}

fn gum_first_order_variance(j: [f64; 8], sigma: &CovMat) -> f64 with Mut {
    var acc: f64 = 0.0
    var i: i32 = 0
    while i < 8 {
        var k: i32 = 0
        while k < 8 {
            acc = acc + j[i] * cm_get(sigma, i, k) * j[k]
            k = k + 1
        }
        i = i + 1
    }
    return acc
}

fn gum_trace_hshs(h: [f64; 36], sigma: &CovMat) -> f64 with Mut {
    var acc: f64 = 0.0
    var i: i32 = 0
    while i < 8 {
        var j: i32 = 0
        while j < 8 {
            let h_ij = hess_get_8(h, i, j)
            var k: i32 = 0
            while k < 8 {
                let s_jk = cm_get(sigma, j, k)
                var l: i32 = 0
                while l < 8 {
                    let h_kl = hess_get_8(h, k, l)
                    let s_li = cm_get(sigma, l, i)
                    acc = acc + h_ij * s_jk * h_kl * s_li
                    l = l + 1
                }
                k = k + 1
            }
            j = j + 1
        }
        i = i + 1
    }
    return acc
}

fn gum_second_order_variance(j: [f64; 8], h: [f64; 36], sigma: &CovMat) -> f64 with Mut, Div {
    let v1 = gum_first_order_variance(j, sigma)
    let trace = gum_trace_hshs(h, sigma)
    return v1 + 0.5 * trace
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { 0.0 - x } else { x }
}

// =============================================================================
// Test: linear function f(x, y) = 3x + 4y
// =============================================================================

fn test_linear() -> f64 with IO, Epistemic, Mut, Div {
    let xm: Knowledge<f64> = measure(1.0, uncertainty: 0.0)
    let ym: Knowledge<f64> = measure(1.0, uncertainty: 0.0)
    let x = xm.value
    let y = ym.value
    // f(x, y) = 3x + 4y — Hessian is identically zero
    let z = 3.0 * x + 4.0 * y
    // Jacobian: ∂z/∂x_k via sensitivity_of
    let j: [f64; 8] = [sensitivity_of(z, 0), sensitivity_of(z, 1), sensitivity_of(z, 2), sensitivity_of(z, 3), sensitivity_of(z, 4), sensitivity_of(z, 5), sensitivity_of(z, 6), sensitivity_of(z, 7)]
    // Hessian: ∂²z/∂x_j∂x_k via hessian_of — all zero for a linear function.
    // NOTE: the compiler's hessian_of(expr, j, k) requires LITERAL integer
    // indices; runtime i32 variables return incorrect values.  For this
    // sanity case we rely on the linear function having H ≡ 0 and leave
    // the default-initialized zero array.  (The PBPK test unrolls explicit
    // hessian_of calls with literal indices.)
    var h: [f64; 36] = [0.0; 36]
    // Sanity witness: confirm H[0,0] and H[0,1] really are zero for 3x+4y.
    h[0] = hessian_of(z, 0, 0)  // expect 0.0
    h[1] = hessian_of(z, 0, 1)  // expect 0.0
    h[8] = hessian_of(z, 1, 1)  // expect 0.0
    // Build sigma: sigma[0,0] = 0.01, sigma[1,1] = 0.04, rest zero
    var sigma = cm_new(8)
    cm_set(&!sigma, 0, 0, 0.01)
    cm_set(&!sigma, 1, 1, 0.04)
    // First-order variance:  9·0.01 + 16·0.04 = 0.73
    let sigma2_1st = gum_first_order_variance(j, &sigma)
    // Second-order variance: should equal first-order because H = 0
    let sigma2_2nd = gum_second_order_variance(j, h, &sigma)
    // Return their absolute difference — must be zero
    return abs_f64(sigma2_2nd - sigma2_1st)
}

fn main() with IO, Epistemic, Mut, Div {
    let diff = test_linear()
    println(diff)  // expect 0.000000
}

