//@ run-pass
//
// Gradient Topology Types (GTT) — β⁹ week-10 regression (loop snapshot/union).
//
// Before this fix, a var mutated inside a while loop would have its VAR_CH_SET
// frozen at the pre-loop state (or emptied if only set in the loop body) because
// the snapshot+union was missing.  After the fix:
//
//   1. VAR_CH_SET is snapshotted before the loop runs (so 0-iteration loops
//      preserve pre-loop topology).
//   2. Post-body topology is unioned with the snapshot at loop exit (so a
//      variable that gains channels inside the loop retains both the pre-loop
//      and post-loop channels — sound conservative upper bound).
//
// This test uses a 1-iteration loop so the body definitely runs, and verifies
// that the channel gained in the loop body is present in the post-loop topology.

fn main() with IO, Epistemic, Mut, Div {
    let k0: Knowledge<f64> = measure(2.0, uncertainty: 0.1)
    let k1: Knowledge<f64> = measure(3.0, uncertainty: 0.1)
    var r: f64 = k0.value    // r has channel 0 (via reassignment fix)
    var i: i64 = 0
    while i < 1 {
        r = k1.value         // r gains channel 1 inside the loop
        i = i + 1
    }
    // Post-loop: VAR_CH_SET[r] should be {ch0} | {ch1} = {ch0, ch1}
    let h00 = hessian_of(r, 0, 0)
    let h11 = hessian_of(r, 1, 1)
    println(h00)
    println(h11)
}

//@ run-pass
//@ expect-stdout: GUM_FO_ANALYTIC_TRANSCENDENTALS_OK
//@ requires: madaros
// First-order GUM propagation through the five transcendentals whose derivative
// is NOT another named function.
//
// The transfer table stored a derivative as a NAME -- sin' = cos, exp' = exp --
// which is exact and free for a set closed under differentiation, and expresses
// nothing outside it. atan' = 1/(1+x^2) has no name, so the lookup returned
// empty and variance_of answered a confident 0.0. Kind 8 carries an id instead
// and EMITS the derivative, from x plus sqrt/sin/cos/exp only -- all backend
// builtins, so nothing here reopens the E221 hole (#2172).
//
// TWO points per function, deliberately. A single point cannot tell a correct
// answer from sigma^2 passing through unscaled: at one x they can coincide.
//
// hessian_of is covered too, as of the second-order wiring:
//   H(atan(x)) = -2x/(1+x^2)^2
//     x=0.5: -1/1.5625   = -0.64
//     x=2.0: -4/25       = -0.16
use math::pure::{atan}

fn near(a: f64, b: f64) -> bool {
    let d = a - b
    if d < 0.0 { return 0.0 - d < 1.0e-7 }
    return d < 1.0e-7
}

fn main() with IO, Mut, Div, Panic, Epistemic {
    let ka: Knowledge<f64> = measure(0.5, uncertainty: 0.1)
    let kb: Knowledge<f64> = measure(2.0, uncertainty: 0.1)
    let x = ka.value
    let y = kb.value

    // Var(atan(x)) = (1/(1+x^2))^2 * sigma^2
    //   x=0.5: (1/1.25)^2 * 0.01 = 0.0064
    //   x=2.0: (1/5)^2   * 0.01 = 0.0004
    let ok = near(variance_of(atan(x)), 0.0064)
        && near(variance_of(atan(y)), 0.0004)
        && near(variance_of(x), 0.01)
        && near(hessian_of(atan(x), 0, 0), 0.0 - 0.64)
    if ok {
        print("GUM_FO_ANALYTIC_TRANSCENDENTALS_OK\n")
    } else {
        print("GUM_FO_ANALYTIC_TRANSCENDENTALS_FAIL\n")
        print("atan(0.5)="); print_f64(variance_of(atan(x))); print(" want 0.006400\n")
        print("atan(2.0)="); print_f64(variance_of(atan(y))); print(" want 0.000400\n")
        print("hess(0.5)="); print_f64(hessian_of(atan(x), 0, 0)); print(" want -0.640000\n")
    }
}

//@ run-pass
// GUM Automated Reporting Test Suite
//
// Validates WS2 automated GUM reporting:
//   1. Cockcroft-Gault CrCl budget — SCr dominates >60%
//   2. Simple 2-input addition — equal contributions ~50% each
//   3. Budget validation — contributions sum to ~100%
//   4. Expanded uncertainty with known coverage factor
//   5. Sensitivity ranking — correct descending order
//   6. Dominant source identification
//   7. Recommendation generation — dominant source case
//   8. Recommendation generation — balanced case
//   9. Report generation and validation
//  10. Report integrity check
//
// Reference: JCGM 100:2008 Section 8 (Reporting)

// ============================================================================
// HELPERS (self-contained, no imports)
// ============================================================================

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn sqrt_f64(x: f64) -> f64 with Mut {
    if x <= 0.0 { return 0.0 }
    var guess = x / 2.0
    if guess < 0.001 { guess = 0.001 }
    var i = 0
    while i < 30 {
        guess = (guess + x / guess) / 2.0
        i = i + 1
    }
    return guess
}

fn max_f64(a: f64, b: f64) -> f64 {
    if a > b { return a }
    return b
}

// ============================================================================
// BUDGET ENTRY
// ============================================================================

struct BudgetEntry {
    source_type: i32,
    estimate: f64,
    std_uncert: f64,
    sensitivity: f64,
    contribution: f64,
    dof: f64
}

fn budget_entry_a(estimate: f64, std_uncert: f64, sensitivity: f64, dof: f64) -> BudgetEntry {
    let contrib = sensitivity * sensitivity * std_uncert * std_uncert
    return BudgetEntry {
        source_type: 0,
        estimate: estimate,
        std_uncert: std_uncert,
        sensitivity: sensitivity,
        contribution: contrib,
        dof: dof
    }
}

fn budget_entry_b(estimate: f64, std_uncert: f64, sensitivity: f64) -> BudgetEntry {
    let contrib = sensitivity * sensitivity * std_uncert * std_uncert
    return BudgetEntry {
        source_type: 1,
        estimate: estimate,
        std_uncert: std_uncert,
        sensitivity: sensitivity,
        contribution: contrib,
        dof: 1.0e30
    }
}

fn empty_entry() -> BudgetEntry {
    return BudgetEntry {
        source_type: 0,
        estimate: 0.0,
        std_uncert: 0.0,
        sensitivity: 0.0,
        contribution: 0.0,
        dof: 1.0
    }
}

// ============================================================================
// UNCERTAINTY BUDGET (4 entries max)
// ============================================================================

struct UncertaintyBudget {
    result_value: f64,
    entry_count: i32,
    e0: BudgetEntry,
    e1: BudgetEntry,
    e2: BudgetEntry,
    e3: BudgetEntry,
    combined_variance: f64,
    combined_std_uncert: f64,
    effective_dof: f64,
    confidence: f64
}

fn budget_new(result_value: f64, confidence: f64) -> UncertaintyBudget {
    return UncertaintyBudget {
        result_value: result_value,
        entry_count: 0,
        e0: empty_entry(),
        e1: empty_entry(),
        e2: empty_entry(),
        e3: empty_entry(),
        combined_variance: 0.0,
        combined_std_uncert: 0.0,
        effective_dof: 0.0,
        confidence: confidence
    }
}

fn get_entry(budget: UncertaintyBudget, idx: i32) -> BudgetEntry {
    if idx == 0 { return budget.e0 }
    if idx == 1 { return budget.e1 }
    if idx == 2 { return budget.e2 }
    if idx == 3 { return budget.e3 }
    return empty_entry()
}

fn add_entry(budget: UncertaintyBudget, entry: BudgetEntry) -> UncertaintyBudget with Mut {
    var result = budget
    let idx = budget.entry_count
    if idx == 0 { result.e0 = entry }
    else if idx == 1 { result.e1 = entry }
    else if idx == 2 { result.e2 = entry }
    else if idx == 3 { result.e3 = entry }
    if idx < 4 {
        result.entry_count = idx + 1
    }
    return result
}

fn add_type_a(budget: UncertaintyBudget, estimate: f64, std_uncert: f64, sensitivity: f64, n_samples: f64) -> UncertaintyBudget with Mut {
    let dof = n_samples - 1.0
    let entry = budget_entry_a(estimate, std_uncert, sensitivity, dof)
    return add_entry(budget, entry)
}

fn add_type_b(budget: UncertaintyBudget, estimate: f64, std_uncert: f64, sensitivity: f64) -> UncertaintyBudget with Mut {
    let entry = budget_entry_b(estimate, std_uncert, sensitivity)
    return add_entry(budget, entry)
}

fn compute_combined(budget: UncertaintyBudget) -> UncertaintyBudget with Mut {
    var result = budget
    var total_var: f64 = 0.0
    if budget.entry_count > 0 {
        total_var = total_var + budget.e0.contribution
    }
    if budget.entry_count > 1 {
        total_var = total_var + budget.e1.contribution
    }
    if budget.entry_count > 2 {
        total_var = total_var + budget.e2.contribution
    }
    if budget.entry_count > 3 {
        total_var = total_var + budget.e3.contribution
    }
    result.combined_variance = total_var
    result.combined_std_uncert = sqrt_f64(total_var)
    return result
}

fn compute_dof(budget: UncertaintyBudget) -> UncertaintyBudget with Mut {
    var result = budget
    let u_c4 = budget.combined_variance * budget.combined_variance
    var denom: f64 = 0.0
    if budget.entry_count > 0 {
        if budget.e0.dof < 1.0e20 {
            let c4 = budget.e0.contribution * budget.e0.contribution
            denom = denom + c4 / budget.e0.dof
        }
    }
    if budget.entry_count > 1 {
        if budget.e1.dof < 1.0e20 {
            let c4 = budget.e1.contribution * budget.e1.contribution
            denom = denom + c4 / budget.e1.dof
        }
    }
    if budget.entry_count > 2 {
        if budget.e2.dof < 1.0e20 {
            let c4 = budget.e2.contribution * budget.e2.contribution
            denom = denom + c4 / budget.e2.dof
        }
    }
    if budget.entry_count > 3 {
        if budget.e3.dof < 1.0e20 {
            let c4 = budget.e3.contribution * budget.e3.contribution
            denom = denom + c4 / budget.e3.dof
        }
    }
    if denom > 1.0e-15 {
        result.effective_dof = u_c4 / denom
    } else {
        result.effective_dof = 1.0e30
    }
    return result
}

fn finalize_budget(budget: UncertaintyBudget) -> UncertaintyBudget with Mut {
    var result = compute_combined(budget)
    result = compute_dof(result)
    return result
}

fn percent_contribution(budget: UncertaintyBudget, idx: i32) -> f64 {
    if budget.combined_variance < 1.0e-15 { return 0.0 }
    let entry = get_entry(budget, idx)
    return 100.0 * entry.contribution / budget.combined_variance
}

