    //   r = alpha*gamma + beta*delta
    //   var(r) = gamma^2 * var(alpha) + alpha^2 * var(gamma)
    //          + delta^2 * var(beta)  + beta^2  * var(delta)
    //          = 4 * (0.01)^2 = 4.0e-4

    // ---- Step 5. Confidence-collapse signature ----
    // mean = 0, variance > 0  =>  signal-to-noise formally undefined.
    if prod_n2 < 0.0000001 {
        if var_r5 > 0.0 {
            if var_r12 > 0.0 {
                print("*** CONFIDENCE COLLAPSE EVENT ***\n")
                print("|E[a*b]|  = 0       (algebraic zero divisor)\n")
                print("var(a*b)  > 0       (uncertainty dominates)\n")
                print("SNR       = undefined (mean = 0, variance > 0)\n")
                print("\nSounio detected the epistemic singularity.\n")
                print("PASS\n")
            } else {
                print("FAIL: var(r12) not positive\n")
            }
        } else {
            print("FAIL: var(r5) not positive\n")
        }
    } else {
        print("FAIL: stdlib sed_mul did not produce algebraic zero\n")
    }
}

//@ run-pass
// &seq[i] single-element borrow — local Seq var, struct FIELD Seq (&obj.field[i]),
// and a struct FIELD Seq through a &Struct REF PARAMETER (the ontology's
// iri_equals(&class.superclasses[i], superclass) pattern, which faulted on a64
// until the a64 borrow path got field-chain handling). For struct elements (heap
// pointers to materialized copies) &seq[i] yields a reference to the element.
struct IRI { id: i64, ns: i64, local: i64 }
fn eq(a: &IRI, b: &IRI) -> bool { a.id == b.id }
struct Bag { items: Seq<IRI>, tag: i64 }

// borrow a field-Seq element through a shared ref parameter, in a loop
fn contains(bag: &Bag, needle: &IRI) -> bool {
    let n = bag.items.count()
    for i in 0..n {
        if eq(&bag.items[i], needle) { return true }
    }
    false
}

fn main() -> i32 with IO, Mut, Panic, Epistemic {
    // local Seq receiver
    var v: Seq<IRI> = seq_new()
    v.push(IRI { id: 7, ns: 1, local: 2 })
    v.push(IRI { id: 9, ns: 3, local: 4 })
    let target = IRI { id: 9, ns: 0, local: 0 }
    if eq(&v[0], &target) { return 1 }     // 7 != 9
    if !eq(&v[1], &target) { return 2 }    // 9 == 9

    // struct-FIELD Seq receiver: &obj.field[i]
    var b: Bag = Bag { items: seq_new(), tag: 0 }
    b.items.push(IRI { id: 42, ns: 0, local: 0 })
    b.items.push(IRI { id: 99, ns: 0, local: 0 })
    let t = IRI { id: 99, ns: 0, local: 0 }
    if eq(&b.items[0], &t) { return 3 }    // 42 != 99
    if !eq(&b.items[1], &t) { return 4 }   // 99 == 99

    // &bag.items[i] through a &Bag ref parameter, in a loop
    if !contains(&b, &t) { return 5 }
    let miss = IRI { id: 123, ns: 0, local: 0 }
    if contains(&b, &miss) { return 6 }

    return 0
}

//@ run-pass
// Phase 1 of Seq<T>: method syntax (.push/.get/.set/.len) + bounds-checked access.
// Method .push uses a local Seq variable receiver (pointer written back on grow).

fn main() -> i32 with IO, Mut, Panic, Epistemic {
    var s: Seq<i64> = seq_new()
    s.push(5)
    s.push(15)
    s.push(25)

    if s.get(0) != 5 { println("seq_methods: FAIL (get 0)"); return 1 }
    if s.get(2) != 25 { println("seq_methods: FAIL (get 2)"); return 1 }

    s.set(1, 150)
    if s.get(1) != 150 { println("seq_methods: FAIL (set/get)"); return 1 }

    if s.len().unwrap("len") != 3 { println("seq_methods: FAIL (len)"); return 1 }

    // grow through method push (forces realloc + pointer writeback via receiver slot)
    var i = 0
    while i < 30 {
        s.push(i)
        i = i + 1
    }
    if s.len().unwrap("len") != 33 { println("seq_methods: FAIL (grown len)"); return 1 }
    if s.get(32) != 29 { println("seq_methods: FAIL (grown last)"); return 1 }
    if s.get(0) != 5 { println("seq_methods: FAIL (grown first survived)"); return 1 }

    println("seq_methods: PASS")
    return 0
}

//@ run-pass
//@ description: Imported theorem::smt assumption/core replay smoke

use theorem::smt::*

fn add_base_or(ctx: &!SmtContext) with Mut, Div {
    var clause: [i32; 8] = [0 as i32; 8]
    clause[0] = 0 as i32  // x
    clause[1] = 2 as i32  // y
    smt_add_clause(ctx, &clause, 2 as i32)
}

fn main() -> i32 with Mut, Div {
    var ctx = smt_new()
    add_base_or(&! ctx)

    if smt_solve(&! ctx) != 1 { return 1 }

    var assumptions: [i32; 8] = [0 as i32; 8]
    assumptions[0] = 1 as i32  // not x
    assumptions[1] = 3 as i32  // not y

    if smt_solve_with_assumptions(&! ctx, &assumptions, 2 as i32) != 0 { return 2 }
    if smt_solve_with_assumptions(&! ctx, &assumptions, 1 as i32) != 1 { return 3 }
    if smt_solve(&! ctx) != 1 { return 4 } // temporary units must be rolled back

    var core: [i32; 8] = [0 as i32; 8]
    core[0] = 0 as i32
    core[1] = 1 as i32
    if smt_check_assumption_core(&! ctx, &assumptions, 2 as i32, &core, 2 as i32) != 1 { return 5 }

    var singleton: [i32; 8] = [0 as i32; 8]
    singleton[0] = 0 as i32
    if smt_check_assumption_core(&! ctx, &assumptions, 2 as i32, &singleton, 1 as i32) != 0 { return 6 }

    var duplicate: [i32; 8] = [0 as i32; 8]
    duplicate[0] = 0 as i32
    duplicate[1] = 0 as i32
    if smt_check_assumption_core(&! ctx, &assumptions, 2 as i32, &duplicate, 2 as i32) != 0 { return 7 }

    var out_of_range: [i32; 8] = [0 as i32; 8]
    out_of_range[0] = 2 as i32
    if smt_check_assumption_core(&! ctx, &assumptions, 2 as i32, &out_of_range, 1 as i32) != 0 { return 8 }

    return 0
}

